for f, (tail, start_m, end_m) in tails.items():
    s = io.open(f, encoding='utf-8').read()
    i = s.find(start_m)
    j = s.find(end_m, i) + len(end_m)
    assert i > 0 and j > i, f + ': якоря не найдены'
    s = s[:i] + tail + s[j:]
    io.open(f, 'w', encoding='utf-8').write(s)
    print('OK', f)
